1	package credit
2	
3	import (
4		"encoding/json"
5		"fmt"
6		"io"
7		"unicode/utf8"
8	)
9	
10	// duplicateFieldError 表示同一个 JSON 对象内出现了重复字段名。
11	type duplicateFieldError struct {
12		field string
13	}
14	
15	func (e *duplicateFieldError) Error() string {
16		return fmt.Sprintf("同一 JSON 对象内字段名 %q 重复出现，字段归属无法确定", e.field)
17	}
18	
19	// scanDuplicateKeys 扫描第一份完整 JSON 值的 token 流，在每个对象内检查
20	// 字段名唯一；第一份值之后的字节一律不读（调用方另行检查完整记录之后是否
21	// 还拼接了多余内容，那里的报错信息需要与本检查区分开）。
22	//
23	// 背景：encoding/json 直接解进结构体（或 map）时，同一对象内的重复键会被
24	// 后一个静默覆盖，读不出“曾经写过两个”，因此在正常结构体解码之前先单独
25	// 扫描一遍 token 流。
26	//
27	// 规则：
28	//   - 同一个 JSON 对象内字段名只能出现一次；重复字段是否相邻、两个值是否
29	//     相同都不影响判定，发现即返回 *duplicateFieldError（含字段名）。
30	//   - 比较以 JSON 解码后的文字为准：Token() 返回的键名已完成 Unicode
31	//     反转义，所以直接写出与 \uXXXX 转义形式的同名键仍算重复。
32	//   - 限制只针对同一对象：对象与数组可任意嵌套，数组各元素、不同课程或
33	//     不同学生等不同对象各自携带同名字段是正常结构，互不比较。
34	//   - 字符串“值”里出现字段名（依据、课程名称等）不是键，不参与检查。
35	func scanDuplicateKeys(r io.Reader) error {
36		type frame struct {
37			isObj bool
38			// expectKey 仅对对象有意义：true 表示下一个字符串 token 是键
39			// （或直接遇到 '}'）；false 表示正在等待该键所对应的值。
40			// 对象内 token 天然按键、值、键、值交替（逗号不产生 token），
41			// 借此区分字符串 token 是键还是普通字符串值。
42			expectKey bool
43			keys      map[string]struct{}
44		}
45		var stack []frame
46		depth := 0
47	
48		push := func(isObj bool) {
49			f := frame{isObj: isObj}
50			if isObj {
51				f.expectKey = true
52				f.keys = map[string]struct{}{}
53			}
54			stack = append(stack, f)
55		}
56		// valueEnded 通知栈顶对象：刚读完一个值（标量或嵌套结构的结束括号）。
57		valueEnded := func() {
58			if n := len(stack); n > 0 {
59				f := &stack[n-1]
60				if f.isObj && !f.expectKey {
61					f.expectKey = true
62				}
63			}
64		}
65	
66		dec := json.NewDecoder(r)
67		for {
68			tok, err := dec.Token()
69			if err == io.EOF {
70				// 空输入交由后续结构体解码报错（空文件在更前面已被拒绝）。
71				return nil
72			}
73			if err != nil {
74				return err
75			}
76			switch t := tok.(type) {
77			case json.Delim:
78				switch t {
79				case '{':
80					depth++
81					push(true)
82				case '[':
83					depth++
84					push(false)
85				case '}', ']':
86					depth--
87					stack = stack[:len(stack)-1]
88					if depth == 0 {
89						// 唯一的顶层值已完整读完，其后内容不在本检查范围。
90						return nil
91					}
92					// 刚结束的嵌套对象/数组本身就是外层键所对应的值。
93					valueEnded()
94				}
95			case string:
96				n := len(stack)
97				if n > 0 && stack[n-1].isObj && stack[n-1].expectKey {
98					// 对象键：Token() 已按解码后的文字返回。
99					if _, dup := stack[n-1].keys[t]; dup {
100						return &duplicateFieldError{field: t}
101					}
102					stack[n-1].keys[t] = struct{}{}
103					stack[n-1].expectKey = false
104					continue
105				}
106				valueEnded()
107				if depth == 0 {
108					return nil // 顶层标量值
109				}
110			default:
111				// number、bool、nil 等标量值。
112				valueEnded()
113				if depth == 0 {
114					return nil
115				}
116			}
117		}
118	}
119	
120	// scanStringUnicode 按原始字节扫描第一份完整 JSON 值里的全部字符串
121	// （字段名与字段值），验证每个字符串都能还原为合法 Unicode 文字：
122	//   - 字符串中直接写入的字节必须是合法 UTF-8；
123	//   - \uXXXX 转义中的高位代理项（U+D800–U+DBFF）必须紧跟一个低位代理项
124	//     （U+DC00–U+DFFF）转义；孤立的低位代理项同样非法。
125	//
126	// 背景：encoding/json 解码时会把非法 UTF-8 字节与未配对的代理项转义静默
127	// 替换成 U+FFFD（“�”）。替换后的学生编号、课程名称或免修依据绝不能被当成
128	// 正常内容继续查询、核对或登记——两个本来不同的编号可能被替换成同一个
129	// 而被误判重复或误判相同。因此必须在结构体解码之前按原始字节拒绝这样的
130	// 文件，整份判为内容损坏，哪怕问题只在一条已拒绝免修的依据里、或在与本次
131	// 核对无关的课程名称里。
132	//
133	// 合法文字不受影响：中文、直接写入的补充平面字符、完整的高低代理项转义对、
134	// 用转义表达的控制字符都保留原意；用户确实写入的“�”（U+FFFD，直接写出
135	// 或 \uFFFD 转义）也是合法文字，不能仅因解码结果含有它就拒绝文件。
136	//
137	// 与 scanDuplicateKeys 一样只扫描第一份完整值：完整记录之后的多余内容
138	// 本来就会被读取方拒绝，无需在此重复判定。
139	func scanStringUnicode(raw []byte) error {
140		i := 0
141		for i < len(raw) && isJSONSpace(raw[i]) {
142			i++
143		}
144		if i >= len(raw) {
145			return nil // 空输入交由后续结构体解码报错
146		}
147		switch raw[i] {
148		case '"':
149			// 顶层就是一个字符串：扫描它本身即可。
150			_, err := scanJSONString(raw, i)
151			return err
152		case '{', '[':
153		default:
154			return nil // 顶层标量（数字、true、false、null）不含字符串
155		}
156		depth := 0
157		for i < len(raw) {
158			switch raw[i] {
159			case '"':
160				j, err := scanJSONString(raw, i)
161				if err != nil {
162					return err
163				}
164				i = j
165			case '{', '[':
166				depth++
167				i++
168			case '}', ']':
169				depth--
170				i++
171				if depth == 0 {
172					// 唯一的顶层值已完整读完，其后内容不在本检查范围。
173					return nil
174				}
175			default:
176				i++
177			}
178		}
179		return nil // 未闭合的结构由 JSON 解析报错
180	}
181	
182	// scanJSONString 扫描从 raw[start]（必须是 '"'）开始的一个字符串字面量，
183	// 返回结束引号之后的下标。字符串内容无法还原为合法 Unicode 文字时报错；
184	// 未闭合、非法转义形式等语法问题留给 JSON 解析器报告，本函数不为此报错。
185	func scanJSONString(raw []byte, start int) (int, error) {
186		i := start + 1
187		for i < len(raw) {
188			c := raw[i]
189			switch {
190			case c == '"':
191				return i + 1, nil
192			case c == '\\':
193				if i+1 >= len(raw) {
194					return len(raw), nil
195				}
196				if raw[i+1] != 'u' {
197					i += 2 // 其他转义的合法性由 JSON 解析器校验
198					continue
199				}
200				v, ok := hex4(raw, i+2)
201				if !ok {
202					i += 2 // 非法 \u 转义形式由 JSON 解析器报错
203					continue
204				}
205				switch {
206				case isHighSurrogate(v):
207					// 高位代理项必须紧跟一个 \uXXXX 形式的低位代理项转义。
208					if i+12 <= len(raw) && raw[i+6] == '\\' && raw[i+7] == 'u' {
209						if v2, ok := hex4(raw, i+8); ok && isLowSurrogate(v2) {
210							i += 12
211							continue
212						}
213					}
214					return 0, fmt.Errorf(
215						`高位代理项转义 \u%04X 后没有紧跟低位代理项转义`, v)
216				case isLowSurrogate(v):
217					return 0, fmt.Errorf(
218						`低位代理项转义 \u%04X 没有对应的高位代理项转义`, v)
219				default:
220					i += 6
221				}
222			case c < utf8.RuneSelf:
223				i++
224			default:
225				// 直接写入的多字节字符必须是合法 UTF-8。注意 U+FFFD 本身
226				// 是合法文字：只有解码失败（size 为 1）才拒绝。
227				r, size := utf8.DecodeRune(raw[i:])
228				if r == utf8.RuneError && size == 1 {
229					return 0, fmt.Errorf(
230						"字符串中直接写入的字节 0x%02X 不是合法 UTF-8", c)
231				}
232				i += size
233			}
234		}
235		return i, nil // 未闭合的字符串由 JSON 解析器报错
236	}
237	
238	func isJSONSpace(c byte) bool {
239		return c == ' ' || c == '\t' || c == '\n' || c == '\r'
240	}
241	
242	func isHighSurrogate(r rune) bool { return 0xD800 <= r && r <= 0xDBFF }
243	func isLowSurrogate(r rune) bool  { return 0xDC00 <= r && r <= 0xDFFF }
244	
245	// hex4 把 b[i:i+4] 读作四位十六进制数。
246	func hex4(b []byte, i int) (rune, bool) {
247		if i+4 > len(b) {
248			return 0, false
249		}
250		var v rune
251		for k := 0; k < 4; k++ {
252			c := b[i+k]
253			var d byte
254			switch {
255			case '0' <= c && c <= '9':
256				d = c - '0'
257			case 'a' <= c && c <= 'f':
258				d = c - 'a' + 10
259			case 'A' <= c && c <= 'F':
260				d = c - 'A' + 10
261			default:
262				return 0, false
263			}
264			v = v*16 + rune(d)
265		}
266		return v, true
267	}
