447	// TestCLISharedEnrollmentResultOwnership 两名学生共享要求编号与修读编号时，
448	// 命令行提交结果必须各归各：s1 通过只影响 s1，s2 随后未通过只影响 s2。
449	func TestCLISharedEnrollmentResultOwnership(t *testing.T) {
450		file := filepath.Join(t.TempDir(), "records.json")
451		setupCLISharedEnrollments(t, file)
452	
453		// s1 提交通过：退出码 0，只有 s1 获得 4 学分、要求满足、来源是本人的 e1。
454		if _, errText, code := runCLI(t, file, "pass", "s1", "e1"); code != 0 {
455			t.Fatalf("s1 首次提交通过应成功且退出码 0，code=%d err=%q", code, errText)
456		}
457		out, _, code := runCLI(t, file, "check", "s1")
458		if code != 0 || !strings.Contains(out, "总学分：4") ||
459			!strings.Contains(out, "要求 r1") || !strings.Contains(out, "已满足") ||
460			!strings.Contains(out, "来源为通过修读 e1") {
461			t.Fatalf("s1 应得 4 学分且要求由本人 e1 满足，code=%d out=%q", code, out)
462		}
463		if strings.Contains(out, "未满足要求：[") {
464			t.Fatalf("s1 不应再有未满足要求，out=%q", out)
465		}
466		// s2 仍是选课：不能因为编号相同拿到学分或被改成通过。
467		out, _, code = runCLI(t, file, "check", "s2")
468		if code != 0 || !strings.Contains(out, "总学分：0") ||
469			!strings.Contains(out, "未满足要求：[r1]") || strings.Contains(out, "通过修读") {
470			t.Fatalf("s2 不应因 s1 的同号通过拿到学分，code=%d out=%q", code, out)
471		}
472		if out, _, _ := runCLI(t, file, "show", "s2"); !strings.Contains(out, "结果：选课") {
473			t.Fatalf("s2 的同号修读应保持选课，out=%q", out)
474		}
475	
476		// s2 随后提交未通过：退出码 0，s2 仍为 0 学分、要求未满足。
477		if _, errText, code := runCLI(t, file, "fail", "s2", "e1"); code != 0 {
478			t.Fatalf("s2 首次提交未通过应成功且退出码 0，code=%d err=%q", code, errText)
479		}
480		out, _, code = runCLI(t, file, "check", "s2")
481		if code != 0 || !strings.Contains(out, "总学分：0") ||
482			!strings.Contains(out, "未满足要求：[r1]") {
483			t.Fatalf("s2 未通过后应仍为 0 学分且要求未满足，code=%d out=%q", code, out)
484		}
485		if out, _, _ := runCLI(t, file, "show", "s2"); !strings.Contains(out, "结果：未通过") {
486			t.Fatalf("s2 的修读应记录为未通过，out=%q", out)
487		}
488		// s1 原来的通过结果、学分与来源均保持不变。
489		out, _, code = runCLI(t, file, "check", "s1")
490		if code != 0 || !strings.Contains(out, "总学分：4") ||
491			!strings.Contains(out, "来源为通过修读 e1") {
492			t.Fatalf("s2 提交未通过不应影响 s1 原有的通过结果，code=%d out=%q", code, out)
493		}
494		if out, _, _ := runCLI(t, file, "show", "s1"); !strings.Contains(out, "结果：通过") {
495			t.Fatalf("s1 的修读应保持通过，out=%q", out)
496		}
497	
498		// 两人结果不同应分别被接受：各自重复提交相同结果幂等成功（退出码 0），
499		// 不能被误判为同一次修读的结果冲突；状态不变。
500		if _, errText, code := runCLI(t, file, "pass", "s1", "e1"); code != 0 {
501			t.Fatalf("s1 重复提交通过应幂等成功，code=%d err=%q", code, errText)
502		}
503		if _, errText, code := runCLI(t, file, "fail", "s2", "e1"); code != 0 {
504			t.Fatalf("s2 重复提交未通过应幂等成功，code=%d err=%q", code, errText)
505		}
506		out, _, _ = runCLI(t, file, "check", "s1")
507		if !strings.Contains(out, "总学分：4") || !strings.Contains(out, "来源为通过修读 e1") {
508			t.Fatalf("幂等重复后 s1 结果应不变，out=%q", out)
509		}
510		out, _, _ = runCLI(t, file, "check", "s2")
511		if !strings.Contains(out, "总学分：0") || !strings.Contains(out, "未满足要求：[r1]") {
512			t.Fatalf("幂等重复后 s2 结果应不变，out=%q", out)
513		}
514	
515		// 各自把本人这份修读改成另一结果：仍按现有规则拒绝（退出码 1）、保留原结果，
516		// 另一名学生的同号修读保持原样。
517		if _, errText, code := runCLI(t, file, "fail", "s1", "e1"); code != 1 {
518			t.Fatalf("s1 通过后改提未通过应拒绝且退出码 1，code=%d err=%q", code, errText)
519		}
520		if _, errText, code := runCLI(t, file, "pass", "s2", "e1"); code != 1 {
521			t.Fatalf("s2 未通过后改提通过应拒绝且退出码 1，code=%d err=%q", code, errText)
522		}
523		if out, _, _ := runCLI(t, file, "show", "s1"); !strings.Contains(out, "结果：通过") {
524			t.Fatalf("被拒绝后 s1 应保留原通过结果，out=%q", out)
525		}
526		if out, _, _ := runCLI(t, file, "show", "s2"); !strings.Contains(out, "结果：未通过") {
527			t.Fatalf("被拒绝后 s2 应保留原未通过结果，out=%q", out)
528		}
529		out, _, _ = runCLI(t, file, "check", "s1")
530		if !strings.Contains(out, "总学分：4") || !strings.Contains(out, "来源为通过修读 e1") {
531			t.Fatalf("改结果被拒后 s1 学分与来源应不变，out=%q", out)
532		}
533		out, _, _ = runCLI(t, file, "check", "s2")
534		if !strings.Contains(out, "总学分：0") || !strings.Contains(out, "未满足要求：[r1]") {
535			t.Fatalf("改结果被拒后 s2 应仍为 0 学分未满足，out=%q", out)
536		}
537	}
538	
539	// TestCLISharedEnrollmentResultOwnershipReversed 交换两名学生的登记与处理顺序：
540	// 先 s2 未通过、再 s1 通过，归属结论必须一致，不依赖先登记或先处理谁。
541	func TestCLISharedEnrollmentResultOwnershipReversed(t *testing.T) {
542		file := filepath.Join(t.TempDir(), "records.json")
543		// 先登记 s2，再登记 s1。
544		for _, st := range [][]string{
545			{"student", "s2"},
546			{"student", "s1"},
547			{"course", "c1", "高等数学", "4"},
548			{"req", "s2", "r1", "c1"},
549			{"req", "s1", "r1", "c1"},
