551			{"enroll", "s1", "r1", "2024春", "e1"},
552		} {
553			if _, errText, code := runCLI(t, file, st...); code != 0 {
554				t.Fatalf("步骤 %v 应成功，code=%d err=%q", st, code, errText)
555			}
556		}
557	
558		if _, _, code := runCLI(t, file, "fail", "s2", "e1"); code != 0 {
559			t.Fatal("先处理的 s2 提交未通过应成功")
560		}
561		if _, _, code := runCLI(t, file, "pass", "s1", "e1"); code != 0 {
562			t.Fatal("后处理的 s1 提交通过应成功")
563		}
564	
565		out, _, code := runCLI(t, file, "check", "s1")
566		if code != 0 || !strings.Contains(out, "总学分：4") ||
567			!strings.Contains(out, "来源为通过修读 e1") {
568			t.Fatalf("s1 应由本人 e1 通过获得 4 学分，code=%d out=%q", code, out)
569		}
570		if out, _, _ := runCLI(t, file, "show", "s1"); !strings.Contains(out, "结果：通过") {
571			t.Fatalf("s1 的修读应为通过，out=%q", out)
572		}
573		out, _, code = runCLI(t, file, "check", "s2")
574		if code != 0 || !strings.Contains(out, "总学分：0") ||
575			!strings.Contains(out, "未满足要求：[r1]") {
576			t.Fatalf("s2 应仍为 0 学分且要求未满足，code=%d out=%q", code, out)
577		}
578		if out, _, _ := runCLI(t, file, "show", "s2"); !strings.Contains(out, "结果：未通过") {
579			t.Fatalf("s2 的修读应为未通过，out=%q", out)
580		}
581	}
582	
583	// TestCLISubmitResultUnknownEnrollmentUnderOtherStudent 修读编号只存在于 s1 名下时，
584	// 用 s2 的名义提交结果必须明确报告 s2 名下没有该修读、退出码 1，不能借用 s1 的
585	// 修读，也不能为 s2 补出新记录；拒绝后两人的状态、要求与总学分与提交前一致，
586	// 记录文件也不应被这次拒绝改写。
587	func TestCLISubmitResultUnknownEnrollmentUnderOtherStudent(t *testing.T) {
588		file := filepath.Join(t.TempDir(), "records.json")
589		for _, st := range [][]string{
590			{"student", "s1"},
591			{"student", "s2"},
592			{"course", "c1", "高等数学", "4"},
593			{"req", "s1", "r1", "c1"},
594			{"enroll", "s1", "r1", "2024春", "e1"},
