// objKind 标识一个 JSON 对象在记录格式中的位置，用于确定该对象有哪些
// “能被现有读取功能识别”的字段名。
type objKind int

const (
	objUnknown objKind = iota // 不属于记录格式的对象（交由结构体解码按未知字段/类型拒绝）
	objFile                   // 记录最外层 fileData
	objCourse                 // courses 数组元素：课程
	objStudent                // students 数组元素：学生
	objRequirement            // requirements 数组元素：课程要求
	objEnrollment             // enrollments 数组元素：修读
	objWaiver                 // waivers 数组元素：免修
)

// recognizedFields 是各类对象能被读取功能识别的字段名（结构体 json 标签
// 原文）。标签名必须与 fileData 及各记录结构体上的 json 标签保持一致。
var recognizedFields = map[objKind][]string{
	objFile: {
		"version", "courses", "students", "requirements",
		"enrollments", "waivers", "nextResultSeq",
	},
	objCourse:      {"id", "name", "credit", "open"},
	objStudent:     {"id"},
	objRequirement: {"id", "student", "course"},
	objEnrollment:  {"id", "student", "req", "term", "result", "resultSeq"},
	objWaiver:      {"id", "student", "req", "basis", "status", "reason"},
}

// foldedFields 在初始化时把各对象的可识别字段折叠为 ASCII 小写：
// encoding/json 按 ASCII 大小写不敏感匹配字段，"credit"、"Credit"、
// "CREDIT" 都会填入同一个结构体字段。扫描器据此判断两个不同写法的键名
// 是否会被读取功能当成同一条记录字段。每个对象自身不存在折叠后相撞的
// 两个标签（否则该格式本身就有歧义）。
var foldedFields = func() map[objKind]map[string]string {
	m := make(map[objKind]map[string]string, len(recognizedFields))
	for kind, tags := range recognizedFields {
		folded := make(map[string]string, len(tags))
		for _, tag := range tags {
			folded[foldASCIIKey(tag)] = tag
		}
		m[kind] = folded
	}
	return m
}()

// fileKeyObjectKind 给出最外层对象某个键所对应数组元素/嵌套对象的类型。
// 记录格式里只有最外层的五个数组承载记录对象。
func fileKeyObjectKind(key string) objKind {
	switch key {
	case "courses":
		return objCourse
	case "students":
		return objStudent
	case "requirements":
		return objRequirement
	case "enrollments":
		return objEnrollment
	case "waivers":
		return objWaiver
	default:
		return objUnknown
	}
}

// foldASCIIKey 按 ASCII 规则把大写字母折叠为小写；非 ASCII 文字原样保留
// （encoding/json 的字段匹配只做 ASCII 大小写不敏感比较，中文等多字节
// 字符本就没有大小写写法）。
func foldASCIIKey(s string) string {
	b := []byte(s)
	changed := false
	for i := range b {
		if 'A' <= b[i] && b[i] <= 'Z' {
			b[i] += 'a' - 'A'
			changed = true
		}
	}
	if !changed {
		return s
	}
	return string(b)
}

// scanDuplicateKeys 扫描第一份完整 JSON 值的 token 流，在每个对象内检查
// 字段归属唯一；第一份值之后的字节一律不读（调用方另行检查完整记录之后
// 是否还拼接了多余内容，那里的报错信息需要与本检查区分开）。
//
// 背景：encoding/json 直接解进结构体（或 map）时，同一对象内的重复键会被
// 后一个静默覆盖，而且结构体字段按 ASCII 大小写不敏感匹配 json 标签——
// 同一门课程同时写 "credit":4 与 "Credit":9 时，标准库读不出“曾经写过
// 两个”，学分直接被后一个值顶替，两个键先后颠倒结果也随之颠倒。因此在
// 正常结构体解码之前先单独扫描一遍 token 流。
//
// 规则：
//   - 同一个 JSON 对象内字段名只能出现一次：完全同名的两个键，或两个
//     键名只有大小写差异、却折叠到同一条可识别记录字段（如 credit 与
//     Credit、student 与 Student、courses 与 COURSES），发现即返回
//     *duplicateFieldError（含规范字段名与两个原始写法）。
//   - 字段顺序、是否相邻、两个值是否相同都不影响判定。
//   - 比较以 JSON 解码后的文字为准：Token() 返回的键名已完成 Unicode
//     反转义，所以 "credit"、"credit" 的 \uXXXX 转义写法与 "Credit"
//     之间任意两两组合都按解码后实际所指的字段判断，不能用转义加大小
//     写的组合绕开限制。
//   - 限制只针对同一对象：对象与数组可任意嵌套，数组各元素、不同课程或
//     不同学生等不同对象各自携带同名字段是正常结构，互不比较。
//   - 不能被读取功能识别的字段不参与折叠归并，但完全同名仍按重复拒绝；
//     真正的未知字段留给随后的 DisallowUnknownFields 解码阶段拒绝。
//   - 字符串“值”里出现字段名（依据、课程名称等）不是键，不参与检查。
func scanDuplicateKeys(r io.Reader) error {
	type frame struct {
		isObj bool
		// kind 标识对象类型（决定有哪些可识别字段）；数组帧不用。
		kind objKind
		// elem 标识数组元素对象的类型（数组帧使用）。
		elem objKind
		// expectKey 仅对对象有意义：true 表示下一个字符串 token 是键
		// （或直接遇到 '}'）；false 表示正在等待该键所对应的值。
		// 对象内 token 天然按键、值、键、值交替（逗号不产生 token），
		// 借此区分字符串 token 是键还是普通字符串值。
		expectKey bool
		// pendingKey 是当前值所属的键，用于判断嵌套对象/数组的类型。
		pendingKey string
		// rawKeys 记录该对象内出现过的全部原始键名（解码后文字）。
		rawKeys map[string]struct{}
		// seen 以 ASCII 小写折叠后的可识别键为索引，记录先出现的原始
		// 写法与其规范字段名；无法识别的键不进此表。
		seen map[string]seenField
	}
	type seenField struct {
		canonical string
		raw       string
	}
	var stack []frame
	depth := 0

	push := func(d json.Delim) {
		switch d {
		case '{':
			kind := objUnknown
			if n := len(stack); n == 0 {
				// 第一份值的根对象即记录最外层；根值不是对象时结构体
				// 解码阶段自会按类型拒绝。
				kind = objFile
			} else if p := &stack[n-1]; p.isObj {
				if p.kind == objFile {
					kind = fileKeyObjectKind(p.pendingKey)
				}
			} else {
				// 对象在数组里：类型由承载它的数组决定（数组类型又由
				// 最外层五个字段之一决定）。
				kind = stack[n-1].elem
			}
			stack = append(stack, frame{
				isObj: true, kind: kind, expectKey: true,
				rawKeys: map[string]struct{}{},
				seen:    map[string]seenField{},
			})
		case '[':
			elem := objUnknown
			if n := len(stack); n > 0 {
				if p := &stack[n-1]; p.isObj {
					if p.kind == objFile {
						elem = fileKeyObjectKind(p.pendingKey)
					}
				} else {
					// 数组嵌套：内层数组元素类型跟随外层数组。
					elem = p.elem
				}
			}
			stack = append(stack, frame{isObj: false, elem: elem})
		}
	}
	// valueEnded 通知栈顶对象：刚读完一个值（标量或嵌套结构的结束括号）。
	valueEnded := func() {
		if n := len(stack); n > 0 {
			f := &stack[n-1]
			if f.isObj && !f.expectKey {
				f.expectKey = true
				f.pendingKey = ""
			}
		}
	}

	dec := json.NewDecoder(r)
	for {
		tok, err := dec.Token()
		if err == io.EOF {
			// 空输入交由后续结构体解码报错（空文件在更前面已被拒绝）。
			return nil
		}
		if err != nil {
			return err
		}
		switch t := tok.(type) {
		case json.Delim:
			switch t {
			case '{', '[':
				depth++
				push(t)
			case '}', ']':
				depth--
				stack = stack[:len(stack)-1]
				if depth == 0 {
					// 唯一的顶层值已完整读完，其后内容不在本检查范围。
					return nil
				}
				// 刚结束的嵌套对象/数组本身就是外层键所对应的值。
				valueEnded()
			}
		case string:
			n := len(stack)
			if n > 0 && stack[n-1].isObj && stack[n-1].expectKey {
				f := &stack[n-1]
				// 对象键：Token() 已按解码后的文字返回，\uXXXX 转义
				// 形式的键名与直接写出的同名键在这里完全不可区分。
				if _, dup := f.rawKeys[t]; dup {
					return &duplicateFieldError{field: t, first: t, second: t}
				}
				f.rawKeys[t] = struct{}{}
				// 只有折叠到同一条可识别记录字段的不同写法才算归属
				// 冲突；未知键的大小写变体随后由结构体解码按未知字段
				// 拒绝（如 "foo" 与 "Foo" 不会被当成任何业务字段）。
				if index := foldedFields[f.kind]; index != nil {
					if canonical, known := index[foldASCIIKey(t)]; known {
						if prev, conflict := f.seen[foldASCIIKey(t)]; conflict {
							return &duplicateFieldError{
								field:  canonical,
								first:  prev.raw,
								second: t,
							}
						}
						f.seen[foldASCIIKey(t)] = seenField{canonical: canonical, raw: t}
					}
				}
				f.expectKey = false
				f.pendingKey = t
				continue
			}
			valueEnded()
			if depth == 0 {
				return nil // 顶层标量值
			}
		default:
			// number、bool、nil 等标量值。
			valueEnded()
			if depth == 0 {
				return nil
			}
		}
	}
}

